package com.searchindex.service

import org.litote.kmongo.*
import org.litote.kmongo.coroutine.*
import org.litote.kmongo.reactivestreams.KMongo
import io.ktor.server.application.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import org.bson.Document
import org.bson.conversions.Bson
import com.mongodb.client.model.Filters
import java.security.MessageDigest

data class SearchRequest(
    val query: String,
    val fields: List<String>? = null,
    val maxResults: Int = 50,
    val facets: Map<String, Any>? = null
)

data class TenantContext(
    val tenantId: String,
    val apiKey: String,
    val permissions: Set<String>
)

class TenantIsolationFilter {
    private val tenantFieldName = "_tenant_id"

    fun buildIsolationFilter(tenantContext: TenantContext): Bson {
        return Filters.eq(tenantFieldName, tenantContext.tenantId)
    }

    fun validateTenantAccess(tenantContext: TenantContext, collection: String): Boolean {
        return tenantContext.permissions.contains("read:$collection")
    }
}

class QueryNormalizer {
    private val reservedOperators = setOf("\$gt", "\$lt", "\$gte", "\$lte", "\$ne", "\$in", "\$nin")
    private val dangerousOperators = setOf("\$where", "\$expr", "\$function", "\$accumulator")

    fun normalizeQueryValue(value: Any?): Any? {
        return when (value) {
            is String -> sanitizeStringValue(value)
            is Map<*, *> -> normalizeMapOperators(value)
            is List<*> -> value.map { normalizeQueryValue(it) }
            else -> value
        }
    }

    private fun sanitizeStringValue(value: String): String {
        // Remove null bytes and control characters
        return value.replace(Regex("[\\x00-\\x1f]"), "")
    }

    private fun normalizeMapOperators(map: Map<*, *>): Map<String, Any?> {
        val result = mutableMapOf<String, Any?>()
        for ((key, value) in map) {
            val strKey = key.toString()
            if (strKey in dangerousOperators) {
                continue // Skip dangerous operators
            }
            if (strKey.startsWith("\$") && strKey !in reservedOperators) {
                continue // Skip unknown operators
            }
            result[strKey] = normalizeQueryValue(value)
        }
        return result
    }
}

class SearchIndexService(
    connectionString: String,
    private val databaseName: String
) {
    private val client = KMongo.createClient(connectionString)
    private val database = client.getDatabase(databaseName)
    private val isolationFilter = TenantIsolationFilter()
    private val queryNormalizer = QueryNormalizer()

    suspend fun search(
        tenantContext: TenantContext,
        collectionName: String,
        request: SearchRequest
    ): List<Document> {
        if (!isolationFilter.validateTenantAccess(tenantContext, collectionName)) {
            throw SecurityException("Tenant lacks access to collection: $collectionName")
        }

        val collection = database.getCollection(collectionName)
        val tenantFilter = isolationFilter.buildIsolationFilter(tenantContext)
        val searchFilter = buildSearchFilter(request)
        val combinedFilter = Filters.and(tenantFilter, searchFilter)

        return collection.find(combinedFilter)
            .limit(request.maxResults.coerceAtMost(100))
            .toList()
    }

    private fun buildSearchFilter(request: SearchRequest): Bson {
        val filters = mutableListOf<Bson>()

        // Text search on query string
        if (request.query.isNotBlank()) {
            val normalizedQuery = queryNormalizer.normalizeQueryValue(request.query) as String
            filters.add(Document("\$text", Document("\$search", normalizedQuery)))
        }

        // Apply facet filters
        request.facets?.let { facets ->
            for ((field, value) in facets) {
                val normalizedValue = queryNormalizer.normalizeQueryValue(value)
                filters.add(buildFacetFilter(field, normalizedValue))
            }
        }

        return if (filters.isEmpty()) Document() else Filters.and(filters)
    }

    private fun buildFacetFilter(field: String, value: Any?): Bson {
        // Validate field name to prevent operator injection via field names
        val sanitizedField = sanitizeFieldName(field)
        return when (value) {
            is Map<*, *> -> Document(sanitizedField, Document(value as Map<String, Any?>))
            is List<*> -> Filters.`in`(sanitizedField, value)
            else -> Filters.eq(sanitizedField, value)
        }
    }

    private fun sanitizeFieldName(field: String): String {
        // Allow dotted paths for nested documents but block operators
        if (field.startsWith("\$") || field.contains("\\x00")) {
            throw IllegalArgumentException("Invalid field name: $field")
        }
        return field
    }
}

fun Application.configureSearchRoutes(service: SearchIndexService) {
    routing {
        post("/api/v1/{collection}/search") {
            val tenantContext = extractTenantContext(call)
                ?: return@post call.respond(HttpStatusCode.Unauthorized, "Invalid tenant credentials")

            val collection = call.parameters["collection"]
                ?: return@post call.respond(HttpStatusCode.BadRequest, "Missing collection")

            val request = call.receive<SearchRequest>()
            try {
                val results = service.search(tenantContext, collection, request)
                call.respond(results)
            } catch (e: SecurityException) {
                call.respond(HttpStatusCode.Forbidden, e.message ?: "Access denied")
            }
        }
    }
}

private fun extractTenantContext(call: ApplicationCall): TenantContext? {
    val apiKey = call.request.header("X-API-Key") ?: return null
    val tenantId = call.request.header("X-Tenant-ID") ?: return null
    // In production, validate API key against stored hash
    val keyHash = MessageDigest.getInstance("SHA-256")
        .digest(apiKey.toByteArray())
        .joinToString("") { "%02x".format(it) }
    // Simplified: return context with default permissions
    return TenantContext(
        tenantId = tenantId,
        apiKey = keyHash,
        permissions = setOf("read:documents", "read:products", "read:articles")
    )
}
